import {env} from 'cloudflare:workers';
import {HttpError,textField} from './http';
import {dayKey,shiftDay} from './game';
type Faculty={id:string;name:string;subject:string};
export function initialDemo(){const day=dayKey(),stamp=new Date().toISOString();return {assignments:[{id:'demo-stacks',subject:'Demo classroom',title:'Build a stack visualizer',instructions:'Explain LIFO and share a short implementation or project link.',due:shiftDay(day,3),created:stamp},{id:'demo-web',subject:'Demo classroom',title:'Design an accessible landing page',instructions:'Build a responsive page with clear headings and keyboard-accessible navigation.',due:shiftDay(day,7),created:stamp}],people:[{id:'DEMO-001',name:'Aarav Mehta',campus:'Jaipur',joined:shiftDay(day,-7),avatar:'🚀'},{id:'DEMO-002',name:'Ishita Verma',campus:'Delhi',joined:shiftDay(day,-7),avatar:'🦉'},{id:'DEMO-003',name:'Kabir Shah',campus:'Bengaluru',joined:shiftDay(day,-5),avatar:'⚡'}],submissions:[{id:'demo-sub-1',assignment:'demo-stacks',user:'DEMO-001',name:'Aarav Mehta',campus:'Jaipur',title:'Build a stack visualizer',response:'My stack supports push, pop and peek. The last element added is the first removed. I tested empty-stack handling.',submitted:stamp,reviewed:null as string|null},{id:'demo-sub-2',assignment:'demo-web',user:'DEMO-002',name:'Ishita Verma',campus:'Delhi',title:'Design an accessible landing page',response:'My page uses semantic headings, labelled inputs, visible keyboard focus and a mobile layout.',submitted:stamp,reviewed:stamp as string|null}],questions:[{id:'demo-q1',subject:'Demo classroom',topic:'Stacks',prompt:'Which operation removes the top item from a stack?',options:['Push','Pop','Peek','Sort'],answer:1,explanation:'Pop removes the most recently added item.',approved:1},{id:'demo-q2',subject:'Demo classroom',topic:'Web accessibility',prompt:'What helps keyboard users see the active control?',options:['A visible focus indicator','Removing outlines','Hover-only styling','Tiny text'],answer:0,explanation:'Visible focus indicators show keyboard users which control is active.',approved:0}],activity:[{user:'DEMO-001',day:shiftDay(day,-1),correct:4,total:5},{user:'DEMO-001',day,correct:5,total:5},{user:'DEMO-002',day,correct:3,total:5},{user:'DEMO-003',day:shiftDay(day,-2),correct:2,total:5}],audits:[{action:'Reviewed Ishita’s sample landing page',created:stamp},{action:'Published two sample assignments',created:stamp}]}}
export async function demoDashboard(f:Faculty,b:any){const db=env.DB!,key='faculty-demo-22222',seed=JSON.stringify(initialDemo());await db.prepare('INSERT OR IGNORE INTO config VALUES(?,?)').bind(key,seed).run();const row=await db.prepare('SELECT value FROM config WHERE key=?').bind(key).first<{value:string}>();const original=row!.value,d=JSON.parse(original),action=b.action??'state';let message='';
if(b.subject&&b.subject!==f.subject)throw new HttpError('Demo access is limited to the sample classroom.',403);
if(action==='assignment-create'){const title=textField(b.title,'Title',120),instructions=textField(b.instructions,'Instructions',5000);if(typeof b.due!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(b.due)||!Number.isFinite(Date.parse(b.due))||new Date(b.due+'T00:00:00Z').toISOString().slice(0,10)!==b.due)throw new HttpError('Choose a valid due date.');d.assignments.unshift({id:crypto.randomUUID(),subject:f.subject,title,instructions,due:b.due,created:new Date().toISOString()});message='Published demo assignment: '+title}
else if(action==='assignment-review'){const s=d.submissions.find((s:any)=>s.id===b.id);if(!s)throw new HttpError('Demo submission not found.',404);if(s.reviewed)throw new HttpError('Already reviewed.',409);s.reviewed=new Date().toISOString();message='Reviewed demo submission from '+s.name}
else if(action==='question'){const topic=textField(b.topic,'Topic',100),prompt=textField(b.prompt,'Question',2000),explanation=textField(b.explanation,'Explanation',3000);if(!Array.isArray(b.options)||b.options.length!==4||!Number.isInteger(b.answer)||b.answer<0||b.answer>3)throw new HttpError('Provide four options and a correct answer.');const options=b.options.map((v:unknown)=>textField(v,'Option',500));if(new Set(options.map((v:string)=>v.toLowerCase())).size!==4)throw new HttpError('Options must be distinct.');d.questions.unshift({id:crypto.randomUUID(),subject:f.subject,topic,prompt,explanation,options,answer:b.answer,approved:0});message='Added demo question: '+topic}
else if(action==='approve'){if(typeof b.approved!=='boolean')throw new HttpError('Approval must be true or false.');const q=d.questions.find((q:any)=>q.id===b.id);if(!q)throw new HttpError('Demo question not found.',404);q.approved=b.approved?1:0;message='Changed demo question approval'}
else if(action!=='state')throw new HttpError('Unknown action.');
if(message){if(d.assignments.length>100||d.questions.length>100)throw new HttpError('Demo limit reached.',409);d.audits.unshift({action:message,created:new Date().toISOString()});d.audits=d.audits.slice(0,30);const result=await db.prepare('UPDATE config SET value=? WHERE key=? AND value=?').bind(JSON.stringify(d),key,original).run();if(!result.meta.changes)throw new HttpError('Another demo update occurred. Refresh and try again.',409);return {ok:true,demo:true}}
const students=d.people.map((p:any)=>{const work=d.submissions.filter((s:any)=>s.user===p.id),quiz=d.activity.filter((a:any)=>a.user===p.id),total=quiz.reduce((n:number,a:any)=>n+a.total,0);return {...p,submitted:work.length,reviewed:work.filter((s:any)=>s.reviewed).length,missing:d.assignments.length-work.length,quizzes:quiz.length,accuracy:total?Math.round(100*quiz.reduce((n:number,a:any)=>n+a.correct,0)/total):null,last:[...work.map((s:any)=>s.submitted.slice(0,10)),...quiz.map((a:any)=>a.day)].sort().at(-1)||null}});return {faculty:f,demo:true,assignments:d.assignments,submissions:d.submissions,students,questions:d.questions,activity:d.activity,audits:d.audits,assignmentXP:30,updatedAt:new Date().toISOString()}}
